- TypeScript interfaces

## Code Example

```typescript
interface LogRecord {
  level: string;
  message: string;
  timestamp: string;
  [key: string]: any;
}

interface Formatter {
  format(record: LogRecord): string;
}

class PlainFormatter implements Formatter {
  format(r: LogRecord) { return `${r.timestamp} [${r.level}] ${r.message}`; }
}

class JsonFormatter implements Formatter {
  format(r: LogRecord) { return JSON.stringify(r); }
}

class FormatterRegistry {
  private map = new Map<string, Formatter>();
  constructor(defaultName: string, private defaultFormatter: Formatter) {
    this.map.set(defaultName, defaultFormatter);
  }
  register(name: string, fmt: Formatter) { this.map.set(name, fmt); }
  get(name: string): Formatter { return this.map.get(name) || this.defaultFormatter; }
}

class Logger {
  private formatterName: string;
  constructor(private registry: FormatterRegistry, formatterName?: string) {
     this.formatterName = formatterName ?? "plain";
  }
  log(level: string, message: string, meta?: any) {
     const rec: LogRecord = { timestamp: new Date().toISOString(), level, message, ...(meta ?? {}) };
     const f = this.registry.get(this.formatterName);
     console.log(f.format(rec));
  }
}
```

